/bin/bash -lc "mkdir -p docs/story checks/setup; cat > checks/setup/neutral.html <<'EOF'
<"'!doctype html><html lang="en"><meta charset="utf-8"><title>Local setup check</title><style>body{font:24px system-ui;padding:64px;background:#f4f3ee;color:#182523}</style><h1>Local setup check</h1><p>Browser and local file rendering are available.</p></html>
EOF
cat > checks/setup/browser-check.mjs <<'"'EOF'
import { chromium } from '/tmp/storyfolio-build-capability-20261011/node_modules/playwright-core/index.mjs';
const browser = await chromium.launch({executablePath:'/tmp/storyfolio-browser-cache/chromium-1248/chrome-linux64/chrome',headless:true,args:['--no-sandbox'],env:{...process.env,LD_LIBRARY_PATH:'/tmp/storyfolio-browser-libs/root/usr/lib/x86_64-linux-gnu'}});
const page=await browser.newPage({viewport:{width:1200,height:800}});
await page.goto(new URL('./neutral.html',import.meta.url).href);
console.log(JSON.stringify({title:await page.title(),heading:await page.locator('h1').innerText(),body:await page.locator('body').boundingBox()}));
await page.screenshot({path:new URL('./neutral.png',import.meta.url).pathname});
await browser.close();
EOF
node checks/setup/browser-check.mjs"

